// crates/domain/order.rs
pub struct OrderId(pub String);
pub enum Order { Draft(Draft), Validated(Validated), Priced(Priced) }

pub fn validate_order(draft: Draft) -> Result<Validated, DomainError> {
    if draft.items.is_empty() { return Err(DomainError::NoItems); }
    Ok(Validated { customer_id: draft.customer_id, items: draft.items })
}

pub fn price_order(validated: Validated) -> Priced {
    let total = validated.items.iter().map(|i| i.price).sum();
    Priced { customer_id: validated.customer_id, total }
}

// crates/domain/repo.rs
pub trait OrderRepo {
    async fn save(&self, order: &Order) -> Result<(), DomainError>;
}

// crates/api/handlers.rs
#[tracing::instrument(skip(repo), fields(user_id = %cmd.customer_id))]
pub async fn handle_create(
    cmd: CreateOrderCmd,
    repo: &dyn OrderRepo,
) -> Result<OrderResponse, AppError> {
    let draft = Order::Draft(Draft::from(cmd));
    let validated = match draft {
        Order::Draft(d) => validate_order(d)?,
        _ => return Err(AppError::InvalidState),
    };
    let priced = price_order(validated);
    repo.save(&Order::Priced(priced.clone())).await?;
    Ok(OrderResponse::from(priced))
}
